export const rectangle=(x=-77.02,y=38.98,size=.04)=>({type:'Polygon',coordinates:[[[x,y],[x+size,y],[x+size,y+size],[x,y+size],[x,y]]]});
export function watershedFixture(){const point={lat:39,lon:-77,key:'39.000000,-77.000000'},position={type:'FeatureCollection',features:[{type:'Feature',id:123,geometry:{type:'LineString',coordinates:[[-77.001,39.01],[-77,38.99]]},properties:{source:'comid',comid:123,identifier:'123'}}]},location={type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'Point',coordinates:[-77.001,39]},properties:{source:'indexed',type:'hydrolocation',comid:123,measure:50,reachcode:'12345678901234'}},{type:'Feature',geometry:{type:'Point',coordinates:[-77,39]},properties:{source:'provided'}}]},delineation={type:'FeatureCollection',features:[{type:'Feature',id:'catchment',properties:{catchmentID:'123'},geometry:rectangle()},{type:'Feature',id:'drainageBasin',properties:{},geometry:rectangle(-77.03,38.99,.06)}]};return {point,position,location,delineation};}
export function watershedFetcher(fixture=watershedFixture()){const calls=[];return {calls,fetcher:async(url,options)=>{calls.push({url,options});return Response.json(url.includes('/position?')?fixture.position:url.includes('/hydrolocation?')?fixture.location:fixture.delineation);}};}
